// SIMULATION: builds the answer a service would send after the candidate signed. It is labelled in the document and in the receipt.
const shipped = Object.fromEntries($('Prepare the shipment').all().map(({ json }) => [json.id, json.payload]));
return $input.all().filter(({ json }) => json.created === true && shipped[json.id]).map(({ json }) => {
  const text = 'SIMULATED SIGNATURE - no e-signature service is connected. Not a legal signature.\n\n' + shipped[json.id].document;
  return { json: { simulated: true, request: `HIRE-${json.id}`, envelope: `SIM-${json.id}`, event: 'signed', signed_at: new Date().toISOString(), document_base64: Buffer.from(text, 'utf8').toString('base64'), method: 'simulation', reference: `SIM-${json.id}` } };
});

// The answer of the e-signature service (webhook) or of the simulation. The sender must show the token; everything else the database checks.
return $input.all().map(({ json: raw }) => {
  const simulated = raw.simulated === true;
  const body = simulated ? raw : (raw.body || {});
  const token = simulated ? '' : String((raw.headers || {})['x-esign-token'] || '');
  const trusted = simulated || (!!$env.ESIGN_WEBHOOK_TOKEN && token === $env.ESIGN_WEBHOOK_TOKEN);
  const id = Number(String(body.request || '').replace(/^HIRE-/, ''));
  const result = ['signed', 'declined', 'expired'].includes(body.event) ? body.event : '';
  if (!trusted || !Number.isInteger(id) || id < 1 || !result) return { json: { authorised: false, reason: !trusted ? 'sender not recognised' : 'answer not readable' } };
  const receipt = {};
  if (body.method) receipt.method = String(body.method).slice(0, 120);
  if (body.reference) receipt.reference = String(body.reference).slice(0, 120);
  return { json: { authorised: true, p_id: id, p_ref: String(body.envelope || ''), p_result: result, p_signed_at: body.signed_at || null, p_document: body.document_base64 || null, p_sha256: body.sha256 || null, p_receipt: receipt } };
});

// One message per outcome. The database decided WHO; this only words it. Pseudonym only, no name.
return $input.all().map(({ json: d }) => {
  const what = `${d.candidate} for ${d.title} (${d.requisition}, ${d.dept})`;
  const text = d.kind === 'ask' ? `The contract for ${what} is ready for your release. Open the hiring request in the Werkbank and release it; nothing is sent to the candidate before that.`
    : d.outcome === 'signed' ? `The contract for ${what} is signed. It is stored with the hiring request in the Werkbank.`
    : d.outcome === 'declined' ? `The candidate declined the contract for ${what}. The request stays approved; the next step is a conversation, not a new approval.`
    : `The contract for ${what} expired without a signature. A new contract needs a new decision by HR.`;
  return { json: { id: d.id, to: d.to, text } };
});
